// Read + sanitize the token, then build a SOQL query for NON-SENSITIVE
// prefill fields only. SSN / DOB are intentionally excluded — the browser
// must never receive them.
const q = $json.query || {};
let token = String(q.token || q.t || '').trim();
token = token.replace(/[^A-Za-z0-9\-_]/g, ''); // prevent SOQL injection

if (!token) {
  return { _notoken: true };
}

const fields = [
  'FirstName','LastName','Company','Email','Phone','MobilePhone',
  'csbs__Amount_Requested__c','AnnualRevenue','csbs__Monthly_Revenue__c',
  'Average_Daily_Balance__c','csbs__Time_in_Business__c','Industry',
  'csbs__Entity_Type__c','Do_you_have_open_business_loans__c',
  'Street','City','State','PostalCode'
];

const soql = `SELECT ${fields.join(',')} FROM Lead WHERE Landing_Page_Token__c='${token}' LIMIT 1`;
const url = 'https://bigthink.my.salesforce.com/services/data/v60.0/query/?q=' + encodeURIComponent(soql);

return { _notoken: false, token, url };

// Map the Salesforce record back to the friendly keys the landing page uses.
const body = $json || {};
const recs = Array.isArray(body.records) ? body.records : [];
if (!recs.length) return { found: false };
const r = recs[0];

const lead = {
  firstname: r.FirstName, lastname: r.LastName, company: r.Company,
  email: r.Email, phone: r.Phone, mobilephone: r.MobilePhone,
  amountrequested: r.csbs__Amount_Requested__c, annualrevenue: r.AnnualRevenue,
  monthlyrevenue: r.csbs__Monthly_Revenue__c, averagedailybalance: r.Average_Daily_Balance__c,
  timeinbusiness: r.csbs__Time_in_Business__c, industry: r.Industry,
  entitytype: r.csbs__Entity_Type__c, hasexistingloans: r.Do_you_have_open_business_loans__c,
  businessstreet: r.Street, businesscity: r.City, businessstate: r.State, businesszip: r.PostalCode
};

const clean = {};
for (const k in lead) {
  const v = lead[k];
  if (v !== null && v !== undefined && v !== '') clean[k] = v;
}
return { found: true, lead: clean };
